import { Button, ToastViewport, useToastQueue } from '@gj-kit/expo-ui';

export function SaveToast() {
  const queue = useToastQueue({ maxVisible: 2 });

  return (
    <>
      <Button label="저장" onPress={() => queue.show({ message: '저장했습니다', variant: 'success' })} />
      <ToastViewport toasts={queue.visibleToasts} onDismiss={queue.dismiss} onPause={queue.pause} onResume={queue.resume} />
    </>
  );
}

